import { spawnSync } from 'node:child_process';
import { existsSync } from 'node:fs';

export const EXECUTABLE_PATH = '/workspace/dataset/test2_executable';

export function hasExecutableBackend() {
  return existsSync(EXECUTABLE_PATH);
}

export function validateWithExecutable(instanceSource, schemaSource) {
  if (!hasExecutableBackend()) {
    return null;
  }

  const result = spawnSync(
    EXECUTABLE_PATH,
    ['--a', instanceSource, '--b', schemaSource],
    {
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
    },
  );

  if (result.error) {
    return null;
  }

  return {
    status: result.status ?? 1,
    stdout: result.stdout ?? '',
    stderr: result.stderr ?? '',
  };
}

