import { buildError, buildHelp, getProgramName } from './cli-format.mjs';
import { validateWithExecutable } from './executable-validator.mjs';
import { ValidationError, validateSources } from './fallback-validator.mjs';

function write(stream, text) {
  stream.write(text);
}

export function run(argv = process.argv) {
  const programName = getProgramName(argv);
  const parsed = parseArguments(argv);

  if (parsed.action === 'help') {
    write(process.stdout, buildHelp(programName));
    return 0;
  }

  if (parsed.action === 'error') {
    write(process.stderr, buildError(programName, parsed.message));
    return 2;
  }

  const executableResult = validateWithExecutable(parsed.a, parsed.b);

  if (executableResult !== null) {
    write(process.stdout, executableResult.stdout);
    write(process.stderr, executableResult.stderr);
    return executableResult.status;
  }

  try {
    validateSources(parsed.a, parsed.b);
    write(process.stdout, 'valid\n');
    return 0;
  } catch (error) {
    if (error instanceof ValidationError) {
      write(process.stdout, `${error.message}\n`);
      return 0;
    }

    throw error;
  }
}

